import {
  Mesh,
  PlaneGeometry,
  MeshStandardNodeMaterial,
  Object3D,
  Color,
} from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new Object3D();
  group.position.set(-2.5, -1.1, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  // Load textures
  const map = ctx.textureLoader.load('/prism-mock/home/nodes/parallax-stack.png');
  const depthMap = ctx.textureLoader.load('/prism-mock/home/nodes/parallax-stack.depth.png');

  // Plane dimensions from atlas source rect (512x320)
  const aspect = 512 / 320; // ≈1.6
  const width = 1.6;
  const height = 1.0;
  const geometry = new PlaneGeometry(width, height, 64, 64);

  // Material with displacement & machined-metal PBR
  const material = new MeshStandardNodeMaterial({
    map,
    displacementMap: depthMap,
    displacementScale: 0.08,
    metalness: 0.55,
    roughness: 0.5,
    clearcoat: 0.25,
    color: new Color('#e8ecf2'), // paper base tint
  });

  const mesh = new Mesh(geometry, material);
  mesh.position.y = 0; // will be animated for hover
  group.add(mesh);

  // Store resources for cleanup
  const resources = { geometry, material, map, depthMap, group, mesh };

  // -------- Cinematic primitives --------
  if (ctx.primitives) {
    ctx.primitives['parallax-scroll'](mesh, { intensity: 0.4 });
    ctx.primitives['depth-rotate'](mesh, { maxDeg: 8 });
  }

  // -------- Entrance animation (weighted-settle) --------
  const entranceTl = gsap.timeline({ defaults: { ease: 'back.out(1.7)', duration: 0.9 } });
  entranceTl.fromTo(
    group.scale,
    { x: 0.96, y: 0.96, z: 0.96 },
    { x: 1, y: 1, z: 1 }
  );

  // -------- Hover interaction (rise-in) --------
  const hoverTl = gsap.timeline({ paused: true });
  hoverTl.to(mesh.position, { y: 0.15, duration: 0.3, ease: 'power3.out' });

  // -------- Event handlers --------
  group.userData.handlers = {
    onPointerEnter: () => {
      hoverTl.play();
    },
    onPointerLeave: () => {
      hoverTl.reverse();
    },
    onClick: () => {
      // Emit 'hub-home.select' event
      group.dispatchEvent(new CustomEvent('hub-home.select', { bubbles: true }));
    },
  };

  // -------- Cleanup --------
  group.userData.cleanup = () => {
    entranceTl.kill();
    hoverTl.kill();
    geometry.dispose();
    material.dispose();
    map.dispose();
    depthMap.dispose();
  };

  return group;
}
